macro_rules! m {
    ($en:expr, $de:expr) => {
        FieldSpec::new($en, $de)
    };
    ($en:expr, $de:expr, $u:expr) => {
        FieldSpec::quantity($en, $de, $u)
    };
    ($en:expr, $de:expr, choices $c:expr) => {
        FieldSpec::choice($en, $de, $c)
    };
}

